pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2) public {
        // Restrict to two distinct block numbers that are strictly increasing in timestamp
        blockNum1 = blockNum1 % 1000000;
        blockNum2 = blockNum2 % 1000000;
        vm.assume(blockNum1 < blockNum2);
        vm.assume(blockNum2 > 1);

        address alice = makeAddr("alice");
        vm.deal(alice, 20 ether);

        // First call
        vm.roll(blockNum1);
        vm.warp(blockNum1 * 1000 + 1);
        vm.prank(alice);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok1);

        // Second call
        vm.roll(blockNum2);
        vm.warp(blockNum2 * 1000 + 2);
        vm.prank(alice);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok2);

        // The balance of C after both calls should be either 0 (if a transfer was triggered on blockNum2)
        // or 20 ether (if no transfer was triggered).
        // The invariant: If blockNum2 is a multiple of 15, the contract balance must be 0;
        // otherwise it must be 20 ether.
        if (blockNum2 % 15 == 0) {
            assertEq(address(c).balance, 0);
        } else {
            assertEq(address(c).balance, 20 ether);
        }
    }
}

