import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 1, 10000 ether);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.deal(actor, amount);

        // Advance block timestamp so the second require passes.
        vm.warp(block.timestamp + 1);

        // Set block.number to a multiple of 15 so the if-branch triggers.
        vm.roll(15);

        // We record whether the fallback call completed without reverting.
        bool ok;
        vm.prank(actor);
        // For the reference contract a successful call requires exactly 10 ether.
        // The fuzzer will supply many amounts; only amount == 10 ether will succeed.
        // For the buggy contract a successful call requires exactly 0 ether.
        // The crucial difference appears when the call succeeds AND the payout branch
        // tries to send the full balance to msg.sender.
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful call we check the invariant:
        // If the call succeeded, then the caller must have received the entire contract balance
        // (which before the transfer was exactly the `value` sent, because the contract started
        // with no balance and `fallback` is the only payable entry). Since the transfer happened
        // inside the same transaction, `address(c).balance` is now 0. If the transfer reverted,
        // the whole transaction would have reverted and `ok` would be false.
        if (ok) {
            // In the reference, this always holds: balance was `amount` sent, all transferred out.
            assertEq(address(c).balance, 0);
        }
    }
}

